enum state { LOGIN_IDLE, LOGIN_BUSY, LOGIN_FAILED, LOGIN_OK };
enum event { EV_SUBMIT, EV_OK, EV_FAIL };
typedef void (*listener)(const struct auth_state *);
static listener subs[8]; static size_t nsubs;
static enum state s = LOGIN_IDLE;
void dispatch(enum event ev) {
    switch (s) { case LOGIN_BUSY: if (ev == EV_OK) s = LOGIN_OK;
                 else if (ev == EV_FAIL) s = LOGIN_FAILED; break;
                 default: if (ev == EV_SUBMIT) s = LOGIN_BUSY; break; }
    struct auth_state snap = snapshot(s);      /* value, not a live pointer */
    for (size_t i = 0; i < nsubs; i++) subs[i](&snap);
}
